package io.mavsdk.kotlin.plugins.mavlink_direct_server

import io.mavsdk.jni.plugins.mavlink_direct_server.NativeMavlinkDirectServer
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.locks.ReentrantReadWriteLock
import kotlin.concurrent.read
import kotlin.concurrent.write

private fun MavlinkDirectServer.MavlinkMessage.toNative():
    NativeMavlinkDirectServer.MavlinkMessage =
    NativeMavlinkDirectServer.MavlinkMessage(
        messageName,
        systemId,
        componentId,
        targetSystemId,
        targetComponentId,
        fieldsJson,
    )

private fun NativeMavlinkDirectServer.MavlinkMessage.toKotlin():
    MavlinkDirectServer.MavlinkMessage =
    MavlinkDirectServer.MavlinkMessage(
        messageName,
        systemId,
        componentId,
        targetSystemId,
        targetComponentId,
        fieldsJson,
    )

private class MavlinkDirectServerNativeImpl(private val handle: Long) : MavlinkDirectServerNative {
    // The read lock keeps `handle` alive for the duration of a native call; destroy()
    // takes the write lock, which waits for in-flight calls to finish. Readers do not
    // exclude each other, so independent calls on this plugin still run concurrently
    // and cancelling a subscription does not queue behind a slow blocking call.
    private val lifecycle = ReentrantReadWriteLock()
    @Volatile private var destroyed = false
    private val activeSubscriptions = ConcurrentHashMap<Long, () -> Unit>()

    private inline fun <Value> withOpen(action: () -> Value): Value = lifecycle.read {
        check(!destroyed) { "MavlinkDirectServer is closed" }
        action()
    }

    override fun sendMessage(message: MavlinkDirectServer.MavlinkMessage): Int = withOpen {
        NativeMavlinkDirectServer.sendMessage(handle, message.toNative())
    }

    override fun subscribeMessage(
        messageName: String,
        callback: (MavlinkDirectServer.MavlinkMessage) -> Unit,
    ): Long = withOpen {
        val subscriptionHandle =
            NativeMavlinkDirectServer.subscribeMessage(
                handle,
                messageName,
                NativeMavlinkDirectServer.MessageCallback { value -> callback(value.toKotlin()) },
            )
        if (subscriptionHandle != 0L) {
            activeSubscriptions[subscriptionHandle] = {
                NativeMavlinkDirectServer.unsubscribeMessage(handle, subscriptionHandle)
            }
        }
        subscriptionHandle
    }

    override fun unsubscribeMessage(subscriptionHandle: Long) {
        // No destroyed check: flow cancellation races teardown, and destroy() already
        // drained the map, so this is a no-op rather than an error after close.
        lifecycle.read { activeSubscriptions.remove(subscriptionHandle)?.invoke() }
    }

    override fun loadCustomXml(xmlContent: String): Int = withOpen {
        NativeMavlinkDirectServer.loadCustomXml(handle, xmlContent)
    }

    override fun destroy() {
        lifecycle.write {
            if (destroyed) return
            destroyed = true
            activeSubscriptions.keys.toList().forEach { subscriptionHandle ->
                activeSubscriptions.remove(subscriptionHandle)?.invoke()
            }
            NativeMavlinkDirectServer.destroy(handle)
        }
    }
}

internal actual fun createMavlinkDirectServerNative(systemHandle: Long): MavlinkDirectServerNative =
    MavlinkDirectServerNativeImpl(NativeMavlinkDirectServer.create(systemHandle))
